package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.net.URI;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate1Test {

  @Test
  void archiveKeyUriStripsEntrySuffixOnlyWhenBangPresent() {
    URI withEntry = URI.create("tar:/tmp/a.tar!/entry/file.txt");
    URI withoutEntry = URI.create("tar:/tmp/a.tar");

    URI expected = URI.create("tar:" + Path.of("/tmp/a.tar").toAbsolutePath());

    assertEquals(expected, ArchiveUriSupport.archiveKeyUri(withEntry, "tar", "tar:"));
    assertEquals(expected, ArchiveUriSupport.archiveKeyUri(withoutEntry, "tar", "tar:"));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate2Test {

  @Test
  void archiveKeyUriAcceptsMatchingSchemeAndRejectsOthers() {
    URI matching = URI.create("TARBALL:/tmp/a.tar!/entry");
    URI result = ArchiveUriSupport.archiveKeyUri(matching, "tarball", "tarball:");
    assertEquals(URI.create("tarball:" + Path.of("/tmp/a.tar").toAbsolutePath()), result);

    URI other = URI.create("zip:/tmp/a.tar");
    IllegalArgumentException ex =
        assertThrows(
            IllegalArgumentException.class,
            () -> ArchiveUriSupport.archiveKeyUri(other, "tarball", "tarball:"));
    assertEquals("Unsupported URI scheme: zip", ex.getMessage());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate3Test {

  @Test
  void archiveKeyUriAcceptsPathAndRejectsMissingPath() {
    URI valid = URI.create("tarballfs:/tmp/some-archive.tar!/entry/file.txt");
    URI result = ArchiveUriSupport.archiveKeyUri(valid, "tarballfs", "tarballfs:");
    URI expected =
        URI.create("tarballfs:" + Path.of("/tmp/some-archive.tar").toAbsolutePath());
    assertEquals(expected, result);

    URI opaque = URI.create("tarballfs:opaque");
    IllegalArgumentException ex =
        assertThrows(
            IllegalArgumentException.class,
            () -> ArchiveUriSupport.archiveKeyUri(opaque, "tarballfs", "tarballfs:"));
    assertEquals("tarballfs URI does not contain a file path: " + opaque, ex.getMessage());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class ArchiveUriSupportMutaGate4Test {

  @Test
  void archiveKeyUriAcceptsNonEmptyPathAndRejectsMissingOrEmptyPath() {
    URI valid = URI.create("tar:/tmp/some-archive.tar!/entry/file.txt");
    URI expected = URI.create("tar:" + Path.of("/tmp/some-archive.tar").toAbsolutePath());
    assertEquals(expected, ArchiveUriSupport.archiveKeyUri(valid, "tar", "tar:"));

    // Opaque URI: getPath() returns null
    URI nullPath = URI.create("tar:opaque");
    assertThrows(
        IllegalArgumentException.class,
        () -> ArchiveUriSupport.archiveKeyUri(nullPath, "tar", "tar:"));

    // Authority only: getPath() returns an empty string
    URI emptyPath = URI.create("tar://host");
    assertThrows(
        IllegalArgumentException.class,
        () -> ArchiveUriSupport.archiveKeyUri(emptyPath, "tar", "tar:"));
  }
}

